class Solution { public int maxPointsInsideSquare(int[][] points,String s){int[] first=new int[26],second=new int[26];Arrays.fill(first,Integer.MAX_VALUE);Arrays.fill(second,Integer.MAX_VALUE);for(int index=0;index<points.length;index++){int label=s.charAt(index)-'a';int radius=Math.max(Math.abs(points[index][0]),Math.abs(points[index][1]));if(radius<first[label]){second[label]=first[label];first[label]=radius;}else if(radius<second[label])second[label]=radius;}int forbidden=Integer.MAX_VALUE;for(int radius:second)forbidden=Math.min(forbidden,radius);int answer=0;for(int[] point:points)if(Math.max(Math.abs(point[0]),Math.abs(point[1]))<forbidden)answer++;return answer;} }
